const mbid = (index: number) => `0000000d-0000-4000-8000-${String(index).padStart(12, '0')}`;
const tags = (extra: Record<string, unknown> = {}) => ({ version: 2, title: null, album: null, artists: [], albumArtists: [], label: null, year: null, discNumber: null, trackNumber: null,
    durationMs: null, identifiers: { barcode: null, catalogNumber: null, isrc: null, musicBrainzReleaseId: null }, flagged: [], ...extra });
/** An import of `count` confirmed files chosen in a folder, each with the given version-2 evidence, and an empty Draft v2. */
function project(count: number, evidence: (index: number) => Record<string, unknown>, rootLabel = 'Synthetic Folder'): AdminImportDocument {
    const manifest: ImportManifest = { rootLabel, files: Array.from({ length: count }, (_unused, index) => ({ slotId: slot(index), filename: `${index}.flac`, relativePath: `${rootLabel}/${index}.flac`, byteLength: 1 })) };
    const assets = manifest.files.map((file, index) => ({ slotId: file.slotId, operationId: mbid(500 + index), state: 'ready', sha256: 'a'.repeat(64), duration: null, tags: evidence(index) }) as unknown as ImportAsset);
    return { _id: new ObjectId(importId), purpose: 'import', draftVersion: 2, draft: defaultDraftV2(manifest), draftOrigins: {}, manifest, media: { assets },
        revision: 3, valueRevision: 0, decisions: [], suggestions: [], receipts: [], updatedAt: new Date(0) } as unknown as AdminImportDocument;
}
/** The run an upload (or, with `submitted`, a submission) starts for `doc`, or one with the given queries. */
function runOf(doc: AdminImportDocument, options: { submitted?: { kind: 'album' | 'song'; text: string }; queries?: PlannedLookupQuery[] } = {}): MetadataLookupRecord {
    const planned = planImportLookup(doc, { folderAvailable: true, ...(options.submitted ? { submitted: options.submitted } : {}) });
    return startLookupRun(null, { importId: doc._id, actorId: actor, grantSource: options.submitted ? 'submit' : 'upload', operationId: mbid(600), automatic: !options.submitted,
        input: planned.input, queries: options.queries ?? planned.plan.queries, fileSet: importLookupFileSet(doc), now: start });
}
