test('fallback queries are sent together only when the searches before them found nothing; a skipped folder fallback spends no folder allowance', async () => {
    const doc = project(2, index => tags({ durationMs: [200_000, 210_000][index] }), 'Synthetic Artist - Synthetic Folder (2013 Remaster)');
    const record = runOf(doc);
    const queries = record.queries.map(query => [(query as { query: MusicBrainzReleaseQuery }).query, (query as { fallback?: true }).fallback === true]);
    // The folder's split respelled is the only fallback: its whole name names no release.
    assert.deepEqual(queries, [[{ artist: 'Synthetic Artist', release: 'Synthetic Folder (2013 Remaster)' }, false],
        [{ release: 'Synthetic Artist - Synthetic Folder (2013 Remaster)' }, false], [{ artist: 'Synthetic Artist', release: 'Synthetic Folder' }, true]]);
    // Both searches find nothing, so the normalized fallback is sent, and finds the release.
    const client = clientOf([searchAnswer({ artist: 'Synthetic Artist', release: 'Synthetic Folder (2013 Remaster)' }, []),
        searchAnswer({ release: 'Synthetic Artist - Synthetic Folder (2013 Remaster)' }, []), searchAnswer({ artist: 'Synthetic Artist', release: 'Synthetic Folder' }, [[mbid(1), 2]]),
        releaseAnswer(mbid(1), [200_000, 210_000])]);
    const done = await drive(record, doc, client);
    assert.deepEqual([done.state, done.outcome, done.queryIndex, done.folderUsed, done.searchComplete, sent(client), done.ranking!.preselection?.basis],
        ['complete', 'candidates', 3, true, true, { searches: 3, details: 1 }, 'onlyMatchingGroup']);
    // Album tags spelled "Sound Track": once the fallbacks start they are all sent, since one spelling alone may find fewer editions.
    const album = project(2, index => tags({ album: 'Synthetic Sound Track', albumArtists: ['Synthetic Ensemble'], durationMs: [200_000, 210_000][index] }));
    const respelled = runOf(album);
    assert.deepEqual(respelled.queries.map(query => [(query as { query: MusicBrainzReleaseQuery }).query, (query as { fallback?: true }).fallback === true]), [
        [{ release: 'Synthetic Sound Track', artist: 'Synthetic Ensemble' }, false], [{ release: 'Synthetic Sound Track' }, false],
        [{ release: 'Synthetic Soundtrack', artist: 'Synthetic Ensemble' }, true], [{ release: 'Synthetic Soundtrack' }, true]]);
    const both = clientOf([searchAnswer({ release: 'Synthetic Sound Track', artist: 'Synthetic Ensemble' }, []), searchAnswer({ release: 'Synthetic Sound Track' }, []),
        searchAnswer({ release: 'Synthetic Soundtrack', artist: 'Synthetic Ensemble' }, [[mbid(1), 2]]), searchAnswer({ release: 'Synthetic Soundtrack' }, [[mbid(1), 2], [mbid(2), 2]]),
        releaseAnswer(mbid(1), [200_000, 210_000]), releaseAnswer(mbid(2), [200_000, 210_000])]);
    const together = await drive(respelled, album, both);
    assert.deepEqual([together.queryIndex, together.candidates.length, sent(both), together.ranking!.groups.length], [4, 2, { searches: 4, details: 2 }, 1]);
    // Without a candidate every fallback is sent, and the run finds no release.
    const empty = clientOf(record.queries.map(query => searchAnswer((query as { query: MusicBrainzReleaseQuery }).query, [])));
    assert.deepEqual([(await drive(record, doc, empty)).outcome, sent(empty).searches], ['noRelease', 3]);
    // A candidate known as the fallbacks start skips them all; a skipped folder fallback is never handed out, so the allowance stays unspent.
    const folderFallback: PlannedLookupQuery = { kind: 'musicBrainzReleaseSearch', query: { release: 'Synthetic Folder' }, basis: 'folder', fallback: true };
    const identified = runOf(doc, { queries: [{ kind: 'musicBrainzRelease', releaseId: mbid(2), basis: 'releaseId' }, folderFallback, { ...folderFallback, query: { release: 'Other' } }] });
    const byId = clientOf([releaseAnswer(mbid(2), [200_000, 210_000])]);
    const kept = await drive(identified, doc, byId);
    assert.deepEqual([kept.state, kept.folderUsed, kept.queryIndex, byId.requests.length], ['complete', false, 3, 1]);
});

test('a comparison is partial when a search returned fewer hits than it reported, the bound left a hit out or stopped a planned query, a search was refused, or the record predates the field', async () => {
    const doc = project(2, one), record = runOf(doc);
    const credited = { release: 'Synthetic Album', artist: 'Synthetic Ensemble' }, bare = { release: 'Synthetic Album' };
    // One matching release among others with three tracks that never match.
    const details = (count: number) => [releaseAnswer(mbid(1), [200_000, 210_000]), ...Array.from({ length: count }, (_unused, index) => releaseAnswer(mbid(10 + index), [1000, 1000, 1000]))];
    const others = (count: number, from = 10): [string, number][] => Array.from({ length: count }, (_unused, index) => [mbid(from + index), 2]);
    const outcome = async (exchanges: LookupExchange[], base = record) => {
        const client = clientOf(exchanges), done = await drive(base, doc, client);
        return { done, client, partial: done.ranking!.disclosure.partialComparison, preselected: done.ranking!.preselection?.candidateKey ?? null, groups: done.ranking!.groups.length };
    };
    const complete = await outcome([searchAnswer(credited, [[mbid(1), 2]]), searchAnswer(bare, [[mbid(1), 2]]), ...details(0)]);
    assert.deepEqual([complete.done.searchComplete, complete.partial, complete.preselected, sent(complete.client)], [true, false, `musicbrainz:${mbid(1)}`, { searches: 2, details: 1 }]);
    // A search that reported more hits than it returned.
    const truncated = await outcome([searchAnswer(credited, [[mbid(1), 2]], 7), searchAnswer(bare, [[mbid(1), 2]]), ...details(0)]);
    assert.deepEqual([truncated.done.searchComplete, truncated.partial, truncated.groups, truncated.preselected], [false, true, 1, null]);
    // The bound left out a release a search offered.
    const leftOut = await outcome([searchAnswer(credited, [[mbid(1), 2], ...others(23)]), searchAnswer(bare, others(3, 40)), ...details(23), releaseAnswer(mbid(40), [1000, 1000, 1000])]);
    assert.deepEqual([leftOut.done.candidates.length, leftOut.done.searchComplete, leftOut.partial, leftOut.preselected], [25, false, true, null]);
    // The bound stopped a planned query before it was sent.
    const stopped = await outcome([searchAnswer(credited, [[mbid(1), 2], ...others(24)]), ...details(24)]);
    assert.deepEqual([stopped.done.queryIndex, stopped.done.searchComplete, stopped.partial, stopped.preselected, sent(stopped.client)], [1, false, true, null, { searches: 1, details: 25 }]);
    // A refused search.
    const first = proceedLookupRun(record, doc, null, start);
    const refused = proceedLookupRun(first.next, doc, { kind: 'refused', action: first.step.action! }, start);
    assert.deepEqual([refused.next.queryIndex, refused.next.searchComplete], [1, false]);
    // A record from a release before the field stays partial, even with complete searches.
    const legacy = { ...record } as Partial<MetadataLookupRecord>;
    delete legacy.searchComplete;
    const old = await outcome([searchAnswer(credited, [[mbid(1), 2]]), searchAnswer(bare, [[mbid(1), 2]]), ...details(0)], legacy as MetadataLookupRecord);
    assert.deepEqual([old.done.searchComplete, old.partial, old.preselected], [false, true, null]);
    // Its only matching group is offered, not applied: one group is no tie, so publication never waits for it.
    assert.deepEqual(lookupAnswersNeeded(old.done, doc, { append: false }), { tie: false, conflicts: [] });
});

test('a release that cannot match never makes a comparison partial: one the bound left out that reported another track count, one that no longer exists, and one whose details failed after reporting another count', async () => {
    const doc = project(2, one), record = runOf(doc);
    const credited = { release: 'Synthetic Album', artist: 'Synthetic Ensemble' }, bare = { release: 'Synthetic Album' };
    const others = (count: number, from: number): [string, number][] => Array.from({ length: count }, (_unused, index) => [mbid(from + index), 2]);
    const details = (ids: string[]) => ids.map(id => releaseAnswer(id, id === mbid(1) ? [200_000, 210_000] : [1000, 1000]));
    // 25 plausible releases fill the bound with the last search; the 3-track release it left out cannot match two files.
    const plausible = [mbid(1), ...others(24, 10).map(([id]) => id)];
    const implausibleLeftOut = clientOf([searchAnswer(credited, [[mbid(1), 2], ...others(19, 10)]), searchAnswer(bare, [...others(5, 29), [mbid(80), 3]]), ...details(plausible)]);
    const complete = await drive(record, doc, implausibleLeftOut);
    assert.deepEqual([complete.candidates.length, complete.searchComplete, complete.ranking!.disclosure.partialComparison, complete.ranking!.preselection?.basis, sent(implausibleLeftOut)],
        [25, true, false, 'onlyMatchingGroup', { searches: 2, details: 25 }]);
    // A left-out release of unknown track count could match: the comparison is partial.
    const unknownLeftOut = clientOf([searchAnswer(credited, [[mbid(1), 2], ...others(19, 10)]), searchAnswer(bare, [...others(5, 29), [mbid(81)]]), ...details(plausible)]);
    const partial = await drive(record, doc, unknownLeftOut);
    assert.deepEqual([partial.searchComplete, partial.ranking!.disclosure.partialComparison, partial.ranking!.preselection], [false, true, null]);
    // A release that no longer exists (404) and a 3-track release whose details stay unavailable through every retry cannot
    // match either: the run completes (unavailable details reported) and still preselects the only matching group.
    const gone = { url: musicBrainzUrls.release(mbid(2)).href, status: 404, headers: { 'content-type': 'application/json' }, body: { error: 'Not Found' } };
    const incomplete = clientOf([searchAnswer(credited, [[mbid(1), 2], [mbid(3), 3]]), searchAnswer(bare, [[mbid(2)]]), releaseAnswer(mbid(1), [200_000, 210_000]), gone]);
    const ended = await drive(record, doc, incomplete);
    assert.deepEqual([ended.state, ended.issue, ended.candidates.map(candidate => [candidate.releaseId, candidate.details]), ended.searchComplete,
        ended.ranking!.disclosure.partialComparison, ended.ranking!.preselection?.candidateKey],
        ['complete', 'sourceUnavailable', [[mbid(1), 'fetched'], [mbid(3), 'failed'], [mbid(2), 'missing']], true, false, `musicbrainz:${mbid(1)}`]);
    // The same failure for a release reporting two tracks could hide a match: partial, nothing preselected.
    const hidden = clientOf([searchAnswer(credited, [[mbid(1), 2], [mbid(3), 2]]), searchAnswer(bare, []), releaseAnswer(mbid(1), [200_000, 210_000])]);
    const hiding = await drive(record, doc, hidden);
    assert.deepEqual([hiding.ranking!.disclosure.partialComparison, hiding.ranking!.preselection, lookupAnswersNeeded(hiding, doc, { append: false }).tie], [true, null, false]);
});

test('details of releases whose reported track count can match are fetched first', async () => {
    const doc = project(2, one), record = runOf(doc);
    // The first search offers a 3-track and an unknown-count release (admitted first, since it may match); the second a 2-track
    // one, whose details are fetched before the 3-track release's although it was found later.
    const client = clientOf([searchAnswer({ release: 'Synthetic Album', artist: 'Synthetic Ensemble' }, [[mbid(1), 3], [mbid(2)]]),
        searchAnswer({ release: 'Synthetic Album' }, [[mbid(3), 2]]), releaseAnswer(mbid(3), [200_000, 210_000]), releaseAnswer(mbid(1), [1000, 1000, 1000]),
        releaseAnswer(mbid(2), [1000, 1000])]);
    const done = await drive(record, doc, client);
    const fetched = client.requests.map(request => /release\/([0-9a-f-]{36})\?/.exec(request.url)?.[1]).filter(Boolean);
    assert.deepEqual([fetched, done.candidates.map(candidate => candidate.releaseId)], [[mbid(2), mbid(3), mbid(1)], [mbid(2), mbid(1), mbid(3)]]);
});

test('a 503/429 is busy and retried after its Retry-After within 2–10 s, later after 2 and 5 minutes, then unavailable; a gate busy or unavailable failure keeps 30 s', async () => {
    // The smoke's submitted run: its first request (busy mode) meets a 503 with Retry-After: 0.
    const doc = project(2, () => tags({ durationMs: 200_000 })), submitted = runOf(doc, { submitted: { kind: 'album', text: 'Synthetic Album' } });
    assert.deepEqual(submitted.queries.map(query => (query as { query: MusicBrainzReleaseQuery }).query), [{ release: 'Synthetic Album' }]);
    const throttled = clientOf([...loadLookupFixture('musicbrainz/synthetic-503-retry-after-0-then-200.json').exchanges, releaseAnswer(mbid(1), [200_000, 200_000])]);
    const first = proceedLookupRun(submitted, doc, null, start);
    assert.equal(first.step.mode, 'busy');
    const failure = await performLookupStep(throttled.musicBrainz, first.step.action!, first.step.mode);
    assert.deepEqual(failure, { kind: 'failed', failure: 'rateLimited', retryAfterMs: 1000 });
    const waiting = proceedLookupRun(first.next, doc, failure, start).next;
    assert.deepEqual([waiting.state, waiting.issue, waiting.retryAt!.getTime() - start.getTime(), waiting.attempts], ['retrying', 'sourceBusy', 2_000, { musicbrainz: 1 }]);
    const modes: string[] = [];
    const done = await drive(waiting, doc, throttled, modes);
    assert.deepEqual([done.state, done.issue, done.outcome, modes, throttled.requests.length], ['complete', null, 'candidates', ['wait', 'wait'], 3]);

    // Failures in a row: the first throttled one follows its Retry-After (clamped), later ones 2 and 5 minutes, then the run ends busy.
    const automatic = runOf(project(2, one)), action = proceedLookupRun(automatic, doc, null, start).next;
    const fail = (record: MetadataLookupRecord, result: LookupStepResult, now = start) => proceedLookupRun(record, doc, result, now).next;
    const limited = (retryAfterMs: number | null): LookupStepResult => ({ kind: 'failed', failure: 'rateLimited', retryAfterMs });
    let record = fail(action, limited(7000));
    const delays: [string, string | null, number | null][] = [[record.state, record.issue, record.retryAt!.getTime() - start.getTime()]];
    for (let attempt = 0; attempt < 3; attempt++) {
        record = fail(record, limited(45_000));
        delays.push([record.state, record.issue, record.retryAt ? record.retryAt.getTime() - start.getTime() : null]);
    }
    assert.deepEqual(delays, [['retrying', 'sourceBusy', 7_000], ['retrying', 'sourceBusy', 120_000], ['retrying', 'sourceBusy', 300_000], ['unavailable', 'sourceBusy', null]]);
    assert.deepEqual([record.ranking, record.outcome, record.attempts], [null, null, { musicbrainz: 4 }]);
    assert.equal(fail(action, limited(45_000)).retryAt!.getTime() - start.getTime(), METADATA_LOOKUP_JOB_LIMITS.rateLimitedRetryMs.maximum);
    // A gate refusal is busy and an outage unavailable: both keep 30 seconds (or a longer Retry-After of at most a minute).
    for (const [result, issue, delay] of [[{ kind: 'failed', failure: 'busy', retryAfterMs: 1000 }, 'sourceBusy', 30_000], [{ kind: 'failed', failure: 'busy', retryAfterMs: 45_000 }, 'sourceBusy', 45_000],
        [{ kind: 'failed', failure: 'unavailable', retryAfterMs: null }, 'sourceUnavailable', 30_000]] as const) {
        const next = fail(action, result);
        assert.deepEqual([next.state, next.issue, next.retryAt!.getTime() - start.getTime()], ['retrying', issue, delay], JSON.stringify(result));
    }
    // A retry past the grant counts as exhausted, the throttled one and the 30-second one alike, so a run never blocks past its grant.
    const late = fail(action, limited(9000), new Date(action.grantExpiresAt.getTime() - 5000));
    assert.deepEqual([late.state, late.issue, late.retryAt], ['unavailable', 'sourceBusy', null]);
    for (const [failure, issue] of [['unavailable', 'sourceUnavailable'], ['busy', 'sourceBusy']] as const) {
        const ended = fail(action, { kind: 'failed', failure, retryAfterMs: null }, new Date(action.grantExpiresAt.getTime() - 10_000));
        assert.deepEqual([ended.state, ended.issue, ended.retryAt, ended.attempts], ['unavailable', issue, null, { musicbrainz: 1 }], failure);
    }
});

