test('Blue Archive tags spelled Sound Track: both exact searches are empty, so the normalized fallbacks are sent together and find the CD and digital editions as a tie', async () => {
    const cd = fixture('8baecda4'), lengths = cd.media.flatMap(medium => medium.tracks.map(track => track.lengthMs!));
    const normalized = 'Blue Archive Original Soundtrack Vol.1 ~Longing for the memorable days~';
    const recordedAnswers = () => [...loadLookupFixture('musicbrainz/release-search-blue-archive-sound-track.json').exchanges,
        ...loadLookupFixture('musicbrainz/release-search-blue-archive-normalized.json').exchanges,
        ...loadLookupFixture('musicbrainz/release-8baecda4-f155-40f6-a173-8f6b98cede5b.json').exchanges, ...loadLookupFixture('musicbrainz/release-8f032fff-c63f-4512-973a-758d6d0da2bd.json').exchanges];
    const outcome = async (albumArtists: string[], extra: LookupExchange[] = []) => {
        const doc = project(39, index => tags({ album: blueArchiveTag, albumArtists, durationMs: lengths[index] + ((index * 7919) % 801) - 400 }));
        const record = runOf(doc), client = clientOf([...recordedAnswers(), ...extra]);
        const done = await drive(record, doc, client);
        return { doc, record, done, client };
    };
    // The album artist tag as the label it really is: every answer was recorded.
    const label = await outcome(['株式会社Yostar']);
    assert.deepEqual(label.record.queries.map(query => (query as { query: MusicBrainzReleaseQuery }).query), [{ release: blueArchiveTag, label: '株式会社Yostar' }, { release: blueArchiveTag },
        { release: normalized, label: '株式会社Yostar' }, { release: normalized }]);
    // The credited names: the respelled credited search was never recorded, so it is answered both ways; the bare respelled search
    // is sent with it either way, so the comparison is the same.
    const credited = { release: normalized, artist: 'ミツキヨ、KARUT、Nor' };
    const subtitleByCredit = loadLookupFixture('musicbrainz/release-search-blue-archive-subtitle.json').exchanges[1].body as { releases: unknown[] };
    const runs = [label, await outcome(['ミツキヨ、KARUT、Nor'], [searchAnswer(credited, [])]),
        await outcome(['ミツキヨ、KARUT、Nor'], [json(searchUrl(credited), { count: 1, offset: 0, releases: subtitleByCredit.releases })])];
    for (const { done, doc, client } of runs) {
        assert.deepEqual([done.state, done.outcome, done.searchComplete, done.queryIndex, sent(client)], ['complete', 'candidates', true, 4, { searches: 4, details: 2 }]);
        assert.ok(decodeURIComponent(client.requests[3].url.replace(/\+/g, ' ')).includes('query=release:"Blue Archive Original Soundtrack Vol.1 \\~Longing for the memorable days\\~"&'));
        assert.deepEqual([done.ranking!.groups.length, done.ranking!.preselection, done.ranking!.disclosure.partialComparison, lookupAnswersNeeded(done, doc, { append: false })],
            [2, null, false, { tie: true, conflicts: [] }]);
    }
});

test('Hotel California at the 100-release page: nine-track editions are admitted and fetched first, the bound stops the bare search, and the digital edition ties with the European CD', async () => {
    const digital = fixture('fa7d3357'), lengths = digital.media[0].tracks.map(track => track.lengthMs!);
    const doc = project(9, index => tags({ album: 'Hotel California', albumArtists: ['Eagles'], artists: ['Eagles'], durationMs: lengths[index] }));
    const record = runOf(doc), client = clientOf(hotelCaliforniaExchanges());
    assert.deepEqual(record.queries.map(query => (query as { query: MusicBrainzReleaseQuery }).query), [{ release: 'Hotel California', artist: 'Eagles' }, { release: 'Hotel California' }]);
    const done = await drive(record, doc, client);
    const searches = sent(client);
    // The derived page offers 26 releases: its 20 nine-track ones first, then five others; the 18-track one left out cannot match.
    assert.deepEqual([done.state, done.queryIndex, done.searchComplete, done.candidates.length, searches], ['complete', 1, false, 25, { searches: 1, details: 25 }]);
    assert.ok(done.candidates.slice(0, 20).every(candidate => candidate.summary?.trackCount === 9) && done.candidates.some(candidate => candidate.releaseId.startsWith('fa7d3357')));
    const fetched = client.requests.map(request => /release\/([0-9a-f-]{36})\?/.exec(request.url)?.[1]).filter(Boolean);
    assert.deepEqual(fetched.slice(0, 20), done.candidates.slice(0, 20).map(candidate => candidate.releaseId));
    assert.ok(searches.searches <= METADATA_LOOKUP_LIMITS.plannedQueries && searches.details <= METADATA_LOOKUP_JOB_LIMITS.candidates);
    const matching = done.ranking!.candidates.filter(candidate => candidate.status === 'matching').map(candidate => candidate.releaseId.slice(0, 8)).sort();
    assert.deepEqual([matching, done.ranking!.groups.length, done.ranking!.preselection, done.ranking!.disclosure.partialComparison], [['cb961c6b', 'fa7d3357'], 2, null, true]);
    assert.deepEqual(lookupAnswersNeeded(done, doc, { append: false }), { tie: true, conflicts: [] });
    assert.equal(client.requests.some(request => request.url.includes('tracks')), false, 'the file count is never sent');

    // The live smoke's case: a page that offered 25 of 83 hits (the recorded first page) leaves the European CD as the only
    // matching group, which is offered but never preselected or needed as an answer.
    const recordedPage = { ...loadLookupFixture('musicbrainz/release-search-hotel-california.json').exchanges[0], url: searchUrl({ release: 'Hotel California', artist: 'Eagles' }) };
    const truncated = clientOf([recordedPage, ...hotelCaliforniaExchanges().filter(exchange => !exchange.url.includes('/ws/2/release?query='))]);
    const smoke = await drive(record, doc, truncated);
    assert.deepEqual([smoke.searchComplete, sent(truncated), smoke.ranking!.groups.map(group => group.representativeKey.slice(12, 20)), smoke.ranking!.preselection,
        smoke.ranking!.disclosure.partialComparison, lookupAnswersNeeded(smoke, doc, { append: false })],
        [false, { searches: 1, details: 25 }, ['cb961c6b'], null, true, { tie: false, conflicts: [] }]);
});

